  (* [comment removed for export] *)
  Lemma pcm_C0 : forall regs m (s : Z),
    rdn SEGS m (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) -> rdn SEGS m (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
    getr regs 2 = Z_to_bv 64 (s - 48) -> getr regs 10 = Z_to_bv 64 0 ->
    exists regs',
      msteps SEGS (mkst regs (0x6d04c : word) m rom) (mkst regs' (0x6304c : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 48) /\ getr regs' 1 = Z_to_bv 64 0x6d1a0
      /\ getr regs' 10 = Z_to_bv 64 0x126e8 /\ getr regs' 11 = Z_to_bv 64 0x12df3 /\ getr regs' 12 = Z_to_bv 64 1
